package com.wizzadrds.theworldremembers.chronicle; import net.minecraft.client.gui.GuiGraphicsExtractor; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component; import java.util.*; public final class ChronicleScreen extends Screen{private final List<String> lines;public ChronicleScreen(List<String> lines){super(Component.literal("The World Remembers — Chronicles"));this.lines=List.copyOf(lines);} @Override protected void init(){} @Override public void extractRenderState(GuiGraphicsExtractor graphics,int mouseX,int mouseY,float delta){super.extractRenderState(graphics,mouseX,mouseY,delta);graphics.text(this.font,"THE WORLD REMEMBERS — CHRONICLES",20,18,0xFFFFFFFF,true);int y=38;int end=Math.min(lines.size(),y/10+22);for(int i=0;i<end;i++){graphics.text(this.font,lines.get(i),20,y,0xFFE0E0E0,false);y+=10;}}}